import spidev

# MCP3208 ADC configuration
ADC_CHANNELS = 8
SPI_BUS = 0
SPI_DEVICE = 0


def initialize_spi():
    """Initialize the SPI connection for the MCP3208."""
    spi_port = spidev.SpiDev()
    try:
        spi_port.open(SPI_BUS, SPI_DEVICE)
        spi_port.max_speed_hz = 1000000  # 1 MHz
        spi_port.mode = 0b00  # SPI mode 0
        spi_port.bits_per_word = 8
        spi_port.cshigh = False
        return spi_port
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return None


def read_adc_channel(spi_port, channel):
    """Read a single channel from the MCP3208."""
    if not 0 <= channel < ADC_CHANNELS:
        print("Invalid ADC channel. Must be between 0 and 7.")
        return -1

    try:
        # Construct SPI message: start bit, single/diff bit, channel bits, don't care
        command = [1, (8 + channel) << 4, 0]
        response = spi_port.xfer2(command)
        # Extract the 12-bit value from the response
        adc_value = ((response[1] & 3) << 8) + response[2]
        return adc_value
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return -1


def convert_to_normalized(adc_value):
    """Convert raw ADC value to a normalized float between 0.0 and 1.0."""
    if adc_value < 0 or adc_value > 4095:
        print("Invalid ADC value. Must be between 0 and 4095.")
        return -1
    return adc_value / 4095.0


def main():
    """Main function to read and process the sensor data."""
    spi_port = initialize_spi()
    if spi_port is None:
        return

    try:
        for channel in range(ADC_CHANNELS):
            adc_value = read_adc_channel(spi_port, channel)
            if adc_value != -1:
                normalized_value = convert_to_normalized(adc_value)
                if normalized_value != -1:
                    print(f"Channel {channel}: Raw={adc_value}, Normalized={normalized_value:.2f}")
                else:
                    print(f"Channel {channel}: Invalid ADC value.")
            else:
                print(f"Channel {channel}: Error reading ADC.")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if spi_port:
            spi_port.close()
            print("SPI connection closed.")


if __name__ == "__main__":
    main()

