import cv2
import sys
import time
import RPi.GPIO as GPIO
from functools import partial

# Constants
CAMERA_INDEX = 0
CAMERA_BACKEND = cv2.CAP_V4L2  # Prefer V4L2 for better compatibility
FACE_CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
RESIZE_WIDTH = 32
RESIZE_HEIGHT = 32
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQUENCY = 50
SLEEP_TIME = 0.02

class HardwareInteractionError(Exception):
    """Custom exception for hardware interaction issues."""
    pass


def initialize_gpio():
    """Initializes GPIO pins and returns a dictionary of pin configurations."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LED_PIN, GPIO.OUT)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        pwm = GPIO.PWM(SERVO_PIN, SERVO_FREQUENCY)
        pwm.start(0)
        return {'led': LED_PIN, 'button': BUTTON_PIN, 'servo': {'pin': SERVO_PIN, 'pwm': pwm}}
    except Exception as e:
        raise HardwareInteractionError(f"GPIO initialization failed: {e}")


def set_led(gpio_dict, state):
    """Sets the LED state."""
    try:
        GPIO.output(gpio_dict['led'], state)
    except Exception as e:
        raise HardwareInteractionError(f"LED control failed: {e}")


def set_servo_angle(gpio_dict, angle):
    """Sets the servo angle."""
    try:
        pwm = gpio_dict['servo']['pwm']
        duty = abs(angle) / 18 + 2
        pwm.ChangeDutyCycle(duty)
    except Exception as e:
        raise HardwareInteractionError(f"Servo control failed: {e}")


def detect_faces(frame, face_cascade):
    """Detects faces in a frame."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))


def draw_rectangles(frame, faces):
    """Draws rectangles around detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)


def process_frame(frame, face_cascade):
    """Resizes and detects faces in a frame."""
    resized_frame = cv2.resize(frame, (RESIZE_WIDTH, RESIZE_HEIGHT))
    return detect_faces(resized_frame, face_cascade)


def main_loop(face_cascade, gpio_dict):
    """Main loop for capturing and processing frames."""
    try:
        camera = cv2.VideoCapture(CAMERA_INDEX, CAMERA_BACKEND)
        if not camera.isOpened():
            raise HardwareInteractionError("Could not open camera.")

        servo_direction = 0

        while True:
            ret, frame = camera.read()
            if not ret:
                print("Error reading frame.")
                break

            faces = process_frame(frame, face_cascade)
            draw_rectangles(frame, faces)

            if faces:
                set_led(gpio_dict, cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
            else:
                set_led(gpio_dict, 0)

            for x, y, w, h in faces:
                center_x = x + w // 2
                servo_direction = (center_x - RESIZE_WIDTH // 2) * 0.5

            set_servo_angle(gpio_dict, servo_direction)

            cv2.imshow("Human Detection", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

            time.sleep(SLEEP_TIME)

    except KeyboardInterrupt:
        print("Exiting...")
    except HardwareInteractionError as e:
        print(f"Hardware error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if 'camera' in locals() and camera.isOpened():
            camera.release()
        cv2.destroyAllWindows()
        if gpio_dict:
            gpio_dict['servo']['pwm'].stop()
            GPIO.cleanup()


if __name__ == "__main__":
    try:
        gpio_dict = initialize_gpio()
        face_cascade = cv2.CascadeClassifier(FACE_CASCADE_PATH)
        if face_cascade.empty():
            raise IOError("Unable to load face cascade classifier.")
        main_loop(face_cascade, gpio_dict)
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        print("Program finished.")

