import atexit
import threading
import time
import logging
import traceback
from typing import Callable, Optional

from flask import Flask, render_template, Response, request, jsonify

from camera import Camera  # Assuming this module exists and provides a Camera class
from config import Config  # Assuming this module exists and provides a Config class
from mail_config import send_email  # Assuming this module exists and provides a send_email function

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# App Globals
app = Flask(__name__)
config = Config()
camera: Optional[Camera] = None

# HTML Templates
index_html = "index.html"


def initialize_camera():
    """Initialize the camera object."""
    global camera
    try:
        camera = Camera(config.resolution, config.framerate)
        camera.vs.start()  # Start the video stream
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        raise  # Re-raise the exception to halt execution


def cleanup_camera():
    """Stop and release the camera resources."""
    global camera
    if camera:
        camera.vs.stop()
        logging.info("Camera stopped.")


def detect_object(frame, classifier):
    """Detect objects in a frame using the specified classifier."""
    try:
        if classifier == "motion_detector":
            # Replace with your motion detection logic if needed
            raise NotImplementedError("Motion detection is not yet implemented.")
        else:
            # Assuming the classifier is a function that takes a frame and returns a boolean
            return classifier(frame)
    except Exception as e:
        logging.error(f"Error detecting object: {e}")
        return False



def generate_frames(classifier: Callable[[any], bool]):  # Add type hint for classifier
    """Generate frames for the video stream."""
    try:
        while True:
            frame = camera.get_frame()
            if config.send_email_notifications and detect_object(frame, classifier):
                try:
                    send_email(frame, config.email_sender_address, config.recipient_email_address, config.email_sender_name, config.email_port, config.email_sender_password, config.email_server_address)
                    logging.info("Email notification sent.")
                except Exception as e:
                    logging.error(f"Error sending email: {e}")

            yield frame
    except Exception as e:
        logging.error(f"Error generating frames: {e}")



@app.route("/", methods=['GET', 'POST'])
def index():
    """Handle the index route."""
    if request.method == 'POST':
        try:
            # Update config based on form data (refine validation if needed)
            config.live_preview = request.form.get('live_preview', type=int) == 1
            config.detection = request.form.get('detection', type=int) == 1
            config.send_email_notifications = request.form.get('send_email_notifications', type=int) == 1
            config.email_sender_address = request.form.get('email_sender_address')
            config.recipient_email_address = request.form.get('recipient_email_address')
            config.email_sender_name = request.form.get('email_sender_name')
            config.email_port = request.form.get('email_port', type=int)
            config.email_sender_password = request.form.get('email_sender_password')
            config.email_server_address = request.form.get('email_server_address')
            config.email_notification_interval = request.form.get('email_notification_interval', type=int)
            config.classifier_name = request.form.get('classifier_name')  # Store classifier name


            logging.info("Configuration updated successfully.")
        except KeyError as e:
            logging.error(f"Missing key in form data: {e}")
            return jsonify({"error": f"Missing key: {e}"}), 400
        except Exception as e:
            logging.error(f"Error processing form data: {e}")
            return jsonify({"error": str(e)}), 500


    return render_template(index_html, classifiers=config.classifiers, config=config) # Pass config directly



@app.route("/video_feed")
def video_feed():
    """Provide the video feed."""
    if config.classifier_name:  # Ensure a classifier is selected
        classifier = config.get_classifier(config.classifier_name)  # Dynamic classifier retrieval
        if classifier:
            return Response(generate_frames(classifier), mimetype='multipart/x-mixed-replace; boundary=frame')
        else:
            logging.error(f"Classifier '{config.classifier_name}' not found.")
            return "Error: Invalid classifier selected.", 404
    else:
        logging.error("No classifier selected.")
        return "Error: No classifier selected.", 404




def main():
    """Main function."""
    initialize_camera()
    atexit.register(cleanup_camera)  # Ensure cleanup on exit

    try:
        app.run(debug=True, host='0.0.0.0', port=5000, use_reloader=False)  # Use threaded=True for better performance
    except Exception as e:
        logging.critical(f"Application error: {e}\n{traceback.format_exc()}")
    finally:
        cleanup_camera()


if __name__ == '__main__':
    main()

