import RPi.GPIO as GPIO
import time
import datetime
import csv
import argparse
import os
import io
import picamera

# Define a class to manage the vibration sensors
class VibrationSensorManager:
    def __init__(self, gpio_pins, log_file, interval, calibration_duration, picture_interval):
        self.gpio_pins = gpio_pins
        self.log_file = log_file
        self.interval = interval
        self.calibration_duration = calibration_duration
        self.picture_interval = picture_interval
        self.baseline_percentages = []
        self.thresholds = []
        self.camera = None
        self.last_picture_time = 0

        # Initialize GPIO
        GPIO.setmode(GPIO.BCM)
        for pin in self.gpio_pins:
            try:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Use pull-down resistor
            except Exception as e:
                print(f"Error setting up GPIO pin {pin}: {e}")
                raise

    def calibrate_sensors(self):
        print("Calibrating sensors...")
        start_time = time.time()
        sensor_readings = {pin: [] for pin in self.gpio_pins}

        while time.time() - start_time < self.calibration_duration:
            for pin in self.gpio_pins:
                sensor_readings[pin].append(GPIO.input(pin))
            time.sleep(self.interval / 10)  # Short delay to avoid busy-waiting

        self.baseline_percentages = []
        for pin in self.gpio_pins:
            high_count = sensor_readings[pin].count(1)
            percentage = (high_count / len(sensor_readings[pin])) * 100
            self.baseline_percentages.append(percentage)
            print(f"Sensor {pin}: Baseline percentage = {percentage:.2f}%")

        # Adjust baseline percentages to account for sensor sensitivity
        # This is a simplified approach and may need calibration for different environments
        self.thresholds = [baseline + 20 for baseline in self.baseline_percentages]  # Add 20% threshold

    def read_sensors(self):
        sensor_states = []
        for pin in self.gpio_pins:
            sensor_states.append(GPIO.input(pin))
        return sensor_states

    def log_data(self, timestamp, sensor_states):
        try:
            with open(self.log_file, 'a', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow([timestamp] + sensor_states)
        except Exception as e:
            print(f"Error writing to log file: {e}")

    def check_thresholds(self, sensor_states):
        alarm_triggered = False
        for i, state in enumerate(sensor_states):
            if state == 1 and self.baseline_percentages[i] < self.thresholds[i]:
                alarm_triggered = True
                break
        return alarm_triggered

    def capture_image(self):
        if self.camera is None:
            return None

        now = datetime.datetime.now()
        if time.time() - self.last_picture_time < self.picture_interval:
            return None

        self.last_picture_time = time.time()
