import RPi.GPIO as GPIO
import time
import signal
import sys

# Define GPIO pins for switches and LEDs
SWITCH_PINS = [4, 5, 6]
LED_PINS = [23, 24]

# Global variables to track LED states
led_states = [False, False]
toggle_counts = [0, 0]


def setup_gpio():
    """Sets up the GPIO pins for switches and LEDs."""
    try:
        GPIO.setmode(GPIO.BCM)
        # Setup switch pins as inputs with pull-up resistors
        for pin in SWITCH_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        # Setup LED pins as outputs
        for pin in LED_PINS:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, False)  # Initialize LEDs to off
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)


def read_switches():
    """Reads the state of the switches and updates LED states."""
    global led_states, toggle_counts

    try:
        for i, pin in enumerate(SWITCH_PINS):
            # Check if switch is pressed (LOW signal)
            if GPIO.input(pin) == GPIO.LOW:
                if i == 0:  # Switch 1 (Toggle LED 1)
                    led_states[0] = not led_states[0]
                    GPIO.output(LED_PINS[0], led_states[0])
                elif i == 1:  # Switch 2 (Toggle LED 2)
                    led_states[1] = not led_states[1]
                    GPIO.output(LED_PINS[1], led_states[1])
                elif i == 2:  # Switch 3 (Toggle LED 2 on every other press)
                    toggle_counts[1] += 1
                    if toggle_counts[1] % 2 == 1:
                        led_states[1] = not led_states[1]
                        GPIO.output(LED_PINS[1], led_states[1])
    except Exception as e:
        print(f"Error reading switches: {e}")


def cleanup(signal, frame):
    """Cleans up GPIO pins and exits the program."""
    print("\nExiting program...")
    GPIO.cleanup()
    sys.exit(0)


if __name__ == "__main__":
    # Set up signal handler for Ctrl+C
    signal.signal(signal.SIGINT, cleanup)

    # Setup GPIO pins
    setup_gpio()

    # Main loop
    try:
        while True:
            read_switches()
            time.sleep(0.05)  # Short delay to avoid excessive CPU usage
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup(None, None)

