import cv2
import pyzbar.pyzbar as pyzbar
import logging
import configparser
import time
import datetime
import threading
import queue
import os
import subprocess
import json
import random

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'motion_threshold': '25',
        'frame_buffer_size': '5',
        'redundancy_time_window': '60',
        'cloud_upload_interval': '60',
        'reinit_delay': '5',
        'log_level': 'INFO',
        'camera_node_0': '/dev/video0',
        'camera_node_1': '/dev/video2',
        'fallback_inventory_file': 'backup_inventory.log'
    }
}

# Global variables
inventory_data = {}
last_scan_times = {}
frame_buffers = {}
frame_buffer_lock = threading.Lock()
config = None
logger = None

def load_config():
    """Loads configuration from config.ini or uses default values."""
    global config
    config = configparser.ConfigParser()
    config.read(CONFIG_FILE)

    # Apply default values if sections or keys are missing
    for section, defaults in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        for key, value in defaults.items():
            if key not in config[section]:
                config[section][key] = value

def setup_logging():
    """Sets up logging to both console and file."""
    global logger
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.DEBUG)  # Set default level, can be overridden by config

    # Console handler
    ch = logging.StreamHandler()
    ch.setLevel(logging.INFO)
    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    ch.setFormatter(formatter)
    logger.addHandler(ch)

    # File handler
    fh = logging.FileHandler('inventory.log')
    fh.setLevel(logging.DEBUG)
    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    fh.setFormatter(formatter)
    logger.addHandler(fh)

    # Set log level from config
    log_level_str = config['DEFAULT'].get('log_level', 'INFO').upper()
    log_level = getattr(logging, log_level_str, logging.INFO)  # Default to INFO
    logger.setLevel(log_level)

def initialize_cameras():
    """Initializes the USB cameras."""
    global frame_buffers
    frame_buffers = {
        0: queue.Queue(maxsize=int(config['DEFAULT']['frame_buffer_size'])),
        1: queue.Queue(maxsize=int(config['DEFAULT']['frame_buffer_size']))
    }

    camera_nodes = {
        0: config['DEFAULT']['camera_node_0'],
        1: config['DEFAULT']['camera_node_1']
    }

    for camera_id, camera_node in camera_nodes.items():
        try:
            cap = cv2.VideoCapture(camera_node)
            if not cap.isOpened():
                raise Exception(f"Failed to open camera at {camera_node}")
            logger.info(f"Camera {camera_id} initialized successfully at {camera_node}")
        except Exception as e:
            logger.error(f"Error initializing camera {camera_id} at {camera_node}: {e}")
            return False
    return True

def read_frame(camera_id, cap):
    """Reads a frame from the specified camera."""
    try:
        ret, frame = cap.read()
        if not ret:
            raise Exception("Failed to read frame")
        return frame
    except Exception as e:
        logger.error(f"Error reading frame from camera {camera_id}: {e}")
        return None

def detect_motion(frame, previous_frame, camera_id):
    """Detects motion between two consecutive frames."""
    try:
        motion_threshold = int(config['DEFAULT']['motion_threshold'])
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (21, 21), 0)

        if previous_frame is None:
            return False

        previous_gray = cv2.cvtColor(previous_frame, cv2.COLOR_BGR2GRAY)
        previous_gray = cv2.GaussianBlur(previous_gray, (21, 21), 0)

        frameDelta = cv2.absdiff(previous_gray, gray)
        thresh = cv2.threshold(frameDelta, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        for contour in contours:
            if cv2.contourArea(contour) < motion_threshold:
                continue
            return True
        return False
    except Exception as e:
        logger.error(f"Error detecting motion in camera {camera_id}: {e}")
        return False

def decode_qr_code(frame):
    """Decodes QR codes from a frame."""
    try:
        decoded_objects = pyzbar.decode(frame)
        return decoded_objects
    except Exception as e:
        logger.error(f"Error decoding QR code: {e}")
        return []

def process_qr_code(data, camera_id):
    """Processes a decoded QR code and updates the inventory."""
    global inventory_data, last_scan_times
    try:
        timestamp = datetime.datetime.now().isoformat()
        product_id = data.data.decode('utf-8')

        # Check for redundancy
        if product_id in inventory_data and timestamp in inventory_data[product_id]:
            if timestamp in last_scan_times and last_scan_times[product_id] == timestamp:
                logger.warning(f"Duplicate scan detected for product {product_id} at {timestamp}")
                return

        # Update inventory data
        if product_id not in inventory_data:
            inventory_data[product_id] = {'count': 0, 'last_scan': timestamp}
        inventory_data[product_id]['count'] += 1
        inventory_data[product_id]['last_scan'] = timestamp

        last_scan_times[product_id] = timestamp
        logger.info(f"Product {product_id} scanned at {timestamp} by camera {camera_id}")

        # Simulate cloud upload
        threading.Thread(target=simulate_cloud_upload, args=(inventory_data,)).start()

    except Exception as e:
        logger.error(f"Error processing QR code: {e}")

def simulate_cloud_upload(inventory_data):
    """Simulates uploading inventory data to a cloud service."""
    try:
        # Simulate network latency
        time.sleep(random.uniform(0.1, 0.5))

        # Simulate cloud service availability
        if random.random() < 0.1:
            raise Exception("Simulated cloud service unavailable")

        # Simulate data corruption
        if random.random() < 0.05:
            raise Exception("Simulated data corruption")

        # Simulate network errors
        if random.random() < 0.01:
            raise Exception("Simulated network error")

        # Simulate successful upload
        logger.info("Inventory data successfully uploaded to cloud service.")

    except Exception as e:
        logger.error(f"Error simulating cloud upload: {e}")

def backup_inventory_data():
    """Backs up the inventory data to a file."""
    try:
        backup_file = config['DEFAULT']['fallback_inventory_file']
        with open(backup_file, 'w') as f:
            json.dump(inventory_data, f)
        logger.info(f"Inventory data backed up to {backup_file}")
    except Exception as e:
        logger.error(f"Error backing up inventory data: {e}")

def reinitialize_camera(camera_id, cap):
    """Reinitializes a camera after a failure."""
    try:
        camera_node = config['DEFAULT']['camera_node_' + str(camera_id)]
        cap.release()
        time.sleep(float(config['DEFAULT']['reinit_delay']))
        cap = cv2.VideoCapture(camera_node)
        if not cap.isOpened():
            raise Exception(f"Failed to reinitialize camera at {camera_node}")
        logger.info(f"Camera {camera_id} reinitialized successfully at {camera_node}")
        return cap
    except Exception as e:
        logger.error(f"Error reinitializing camera {camera_id}: {e}")
        return None

def main():
    """Main function to run the QR code inventory system."""
    global inventory_data, last_scan_times, frame_buffers

    load_config()
    setup_logging()

    if not initialize_cameras():
        logger.error("Failed to initialize cameras. Exiting.")
        return

    camera_nodes = {
        0: config['DEFAULT']['camera_node_0'],
        1: config['DEFAULT']['camera_node_1']
    }

    caps = {}
    for camera_id, camera_node in camera_nodes.items():
        try:
            caps[camera_id] = cv2.VideoCapture(camera_node)
        except Exception as e:
            logger.error(f"Failed to open camera {camera_id}: {e}")
            return

    previous_frames = {}
    for camera_id in caps:
        previous_frames[camera_id] = None

    last_cloud_upload_time = time.time()

    def camera_worker(camera_id, cap):
        """Worker function to process frames from a camera."""
        global frame_buffers
        while True:
            frame = read_frame(camera_id, cap)
            if frame is None:
                logger.warning(f"Failed to read frame from camera {camera_id}. Reinitializing...")
                cap = reinitialize_camera(camera_id, cap)
                if cap is None:
                    logger.error(f"Failed to reinitialize camera {camera_id}. Exiting camera worker.")
                    return
                continue

            try:
                with frame_buffer_lock:
                    if frame_buffers[camera_id].full():
                        frame_buffers[camera_id].get()  # Discard oldest frame
                    frame_buffers[camera_id].put(frame)
            except Exception as e:
                logger.error(f"Error putting frame in buffer for camera {camera_id}: {e}")

            try:
                with frame_buffer_lock:
                    if not frame_buffers[camera_id].empty():
                        current_frame = frame_buffers[camera_id].get()
                        previous_frame = frame_buffers[camera_id].get()
                        while previous_frame is None:
                            previous_frame = frame_buffers[camera_id].get()
                            time.sleep(0.01)
                        frame_buffers[camera_id].put(current_frame)
                        frame_buffers[camera_id].put(previous_frame)

                        if detect_motion(current_frame, previous_frame, camera_id):
                            decoded_objects = decode_qr_code(current_frame)
                            for obj in decoded_objects:
                                process_qr_code(obj, camera_id)
            except Exception as e:
                logger.error(f"Error processing frames from camera {camera_id}: {e}")

    # Start camera workers
    threads = []
    for camera_id, cap in caps.items():
        thread = threading.Thread(target=camera_worker, args=(camera_id, cap))
        threads.append(thread)
        thread.daemon = True  # Allow main thread to exit even if this thread is running
        thread.start()

    # Watchdog timer
    last_activity_time = time.time()
    watchdog_interval = 30  # Seconds

    try:
        while True:
            time.sleep(1)
            last_activity_time = time.time()

            # Check for cloud upload interval
            if time.time() - last_cloud_upload_time >= float(config['DEFAULT']['cloud_upload_interval']):
                last_cloud_upload_time = time.time()
                threading.Thread(target=simulate_cloud_upload, args=(inventory_data,)).start()

            # Check for watchdog timeout
            if time.time() - last_activity_time > watchdog_interval:
                logger.critical("Watchdog timeout! Restarting program...")
                os.execv(__file__, ['python'] + sys.argv)  # Restart the script

    except KeyboardInterrupt:
        logger.info("Exiting program...")
    finally:
        for camera_id, cap in caps.items():
            cap.release()
        cv2.destroyAllWindows()
        logger.info("Program terminated.")

if __name__ == "__main__":
    import sys
    main()

