import io
import cv2
import numpy as np

class CameraStreamBuffer:
    def __init__(self, c, o):
        self.c = c
        self.o = o
        self.b = io.BytesIO()

    def write(self, d):
        if self.c.frame_available:
            self.o.write(self.b.getvalue())
            self.b.seek(0)
            self.b.truncate()
        self.b.write(d)

    def flush(self):
        self.o.write(self.b.getvalue())
        self.b.seek(0)
        self.b.truncate()


class MotionDetectionBuffer:
    def __init__(self, f, d):
        self.f = f
        self.d = d
        self.b = io.BytesIO()
        self.p = None
        self.c = None

    def write(self, d):
        self.b.write(d)
        if self.d.frame_available:
            try:
                f = self.b.getvalue()
                if len(f) > 2 and f[0] == 0xFF and f[1] == 0xD8:
                    a = np.frombuffer(f, dtype=np.uint8)
                    self.c = cv2.imdecode(a, cv2.IMREAD_COLOR)
                    if self.c is not None and self.p is not None:
                        self.f(self.p.copy(), self.c.copy())
                    self.p = self.c.copy()
                    self.b.seek(0)
                    self.b.truncate()
            except Exception as e:
                print(e)

