import cv2
import time
import sys
from functools import partial

# Constants for display
WINDOW_TITLE = "Face Detection"
WINDOW_WIDTH = 640
WINDOW_HEIGHT = 480

# Cascade classifier path
CASCADE_CLASSIFIER_PATH = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'

def initialize_camera(width=WINDOW_WIDTH, height=WINDOW_HEIGHT):
    """Initializes the camera and sets resolution."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, width)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, height)
        return cap
    except IOError as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

def load_cascade_classifier(cascade_path):
    """Loads the Haar Cascade Classifier."""
    try:
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            raise IOError(f"Unable to load cascade classifier: {cascade_path}")
        return face_cascade
    except IOError as e:
        print(f"Error loading cascade classifier: {e}")
        sys.exit(1)

def convert_to_grayscale(frame):
    """Converts a frame to grayscale."""
    return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

def detect_faces(gray_frame, face_cascade, scale_factor=1.3, min_neighbors=5):
    """Detects faces in a grayscale frame."""
    return face_cascade.detectMultiScale(gray_frame, scaleFactor=scale_factor, minNeighbors=min_neighbors, minSize=(30, 30))

def draw_rectangles(frame, faces):
    """Draws rectangles around detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
    return frame

def display_frame(frame, window_title=WINDOW_TITLE):
    """Displays the frame in a window."""
    cv2.imshow(window_title, frame)

def process_frame(frame, face_cascade):
    """Processes a single frame, including conversion to grayscale, face detection, and rectangle drawing."""
    gray_frame = convert_to_grayscale(frame)
    faces = detect_faces(gray_frame, face_cascade)
    frame_with_rectangles = draw_rectangles(frame, faces)
    return frame_with_rectangles

def main():
    """Main function to run the face detection."""
    try:
        face_cascade = load_cascade_classifier(CASCADE_CLASSIFIER_PATH)
        cap = initialize_camera()
        cv2.startWindowThread() # Start the window thread for non-blocking display

        while True:
            ret, frame = cap.read()
            if not ret:
                print("Failed to grab frame")
                break

            processed_frame = process_frame(frame, face_cascade)
            display_frame(processed_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if 'cap' in locals():
            cap.release()
        cv2.destroyAllWindows()
        cv2.waitKey(1)

if __name__ == "__main__":
    main()

