import time
import sys
import smbus
import RPi.GPIO as GPIO
from bmp280 import BMP280

# Constants
I2C_BUS = 1
LED_PINS = [17, 27, 22]
PRESSURE_THRESHOLDS = [990, 1010]
ERROR_LOG = "error.log"

def log_error(message):
    """Logs an error message with a timestamp to error.log."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"CRITICAL ERROR: Could not write to log file: {e}")

def initialize_gpio():
    """Initializes GPIO pins for LEDs."""
    GPIO.setmode(GPIO.BCM)
    for pin in LED_PINS:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)  # Ensure LEDs are off initially

def initialize_sensor():
    """Initializes the BMP280 sensor."""
    try:
        bus = smbus.SMBus(I2C_BUS)
        bmp280 = BMP280(i2c_dev=bus)
        time.sleep(1)  # Allow sensor to stabilize
        return bmp280
    except Exception as e:
        log_error(f"Failed to initialize BMP280 sensor: {e}")
        print("BMP280 sensor initialization failed. Check error.log")
        sys.exit(1)

def get_pressure(bmp280):
    """Reads pressure from the BMP280 sensor."""
    try:
        return bmp280.get_pressure()
    except Exception as e:
        log_error(f"Failed to read pressure: {e}")
        return None

def set_leds(pressure):
    """Sets the LED states based on pressure levels."""
    try:
        if pressure < PRESSURE_THRESHOLDS[0]:
            GPIO.output(LED_PINS[0], GPIO.HIGH)
            GPIO.output(LED_PINS[1], GPIO.LOW)
            GPIO.output(LED_PINS[2], GPIO.LOW)
        elif PRESSURE_THRESHOLDS[0] <= pressure < PRESSURE_THRESHOLDS[1]:
            GPIO.output(LED_PINS[0], GPIO.LOW)
            GPIO.output(LED_PINS[1], GPIO.HIGH)
            GPIO.output(LED_PINS[2], GPIO.LOW)
        else:
            GPIO.output(LED_PINS[0], GPIO.LOW)
            GPIO.output(LED_PINS[1], GPIO.LOW)
            GPIO.output(LED_PINS[2], GPIO.HIGH)
    except Exception as e:
        log_error(f"Failed to set LEDs: {e}")

def main():
    """Main function to read pressure and control LEDs."""
    try:
        initialize_gpio()
        bmp280 = initialize_sensor()

        while True:
            pressure = get_pressure(bmp280)
            if pressure is not None:
                print(f"Pressure: {pressure:.2f} hPa")
                set_leds(pressure)
            time.sleep(5)

    except KeyboardInterrupt:
