import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Define sensor reading interval in seconds
READING_INTERVAL = 2

def initialize_i2c_bus():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
        return multiplexer
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_sensors(multiplexer):
    """Initializes the BME280 and TSL2591 sensors."""
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0])
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
        return bme280_sensor, tsl2591_sensor
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None, None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light data from the sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light = tsl2591_sensor.lux
        return temperature, humidity, light
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def print_sensor_data(temperature, humidity, light):
    """Prints the sensor data to the console."""
    if all(v is not None for v in [temperature, humidity, light]):
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light:.2f} lux")

def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c_bus()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor, tsl2591_sensor = initialize_sensors(multiplexer)
    if bme280_sensor is None or tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light = read_sensor_data(bme280_sensor, tsl2591_sensor)
            print_sensor_data(temperature, humidity, light)
            time.sleep(READING_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

