import serial
import time
import csv
import sys

# Define the serial port and baud rate
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1  # seconds

# CSV log file name
CSV_FILE = 'temperature_log.csv'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)


def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print(f"Warning: Invalid data received: {line}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None


def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32


def log_temperature(csv_file, celsius, fahrenheit):
    """Logs the temperature data to a CSV file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(csv_file, 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to CSV file: {e}", file=sys.stderr)


def main():
    """Main function to read temperature and log data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    # Write header row only if the file is empty
    try:
        if serial_connection.in_waiting == 0:
            with open(CSV_FILE, 'w', newline='') as csvfile:
                csv_writer = csv.writer(csvfile)
                csv_writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])

    except IOError as e:
        print(f"Error writing header to CSV file: {e}", file=sys.stderr)
        serial_connection.close()
        sys.exit(1)

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)

            if temperature_celsius is not None:
                temperature_fahrenheit = convert_to_fahrenheit(temperature_celsius)
                log_temperature(CSV_FILE, temperature_celsius, temperature_fahrenheit)
                print(f"Temperature: {temperature_celsius:.2f}°C, {temperature_fahrenheit:.2f}°F")

            time.sleep(1)  # Reduced CPU usage

    except KeyboardInterrupt:
        print("\nExiting program.")

    finally:
        serial_connection.close()
        print("Serial port closed.")


if __name__ == "__main__":
    main()

