import time
import Adafruit_DHT

# Sensor and pin configuration
DHT_SENSOR = Adafruit_DHT.DHT22
DHT_PIN = 22

# Function to read sensor data
def read_dht22_data():
    """
    Reads temperature and humidity from the DHT22 sensor.
    Handles potential errors and retries.
    """
    max_retries = 2
    for attempt in range(max_retries + 1):
        try:
            humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)

            if temperature is not None and humidity is not None:
                # Data validation: check if the readings are within reasonable ranges
                if -40 <= temperature <= 80 and 0 <= humidity <= 100:
                    return temperature, humidity
                else:
                    print(f"Warning: Sensor reading out of range on attempt {attempt + 1}")
            else:
                print(f"Warning: Failed to read sensor data on attempt {attempt + 1}")

        except RuntimeError as error:
            # DHT sensor errors happen quite often, keep trying
            print(f"Error: {error.args[0]} on attempt {attempt + 1}")
            time.sleep(0.1)
        except Exception as error:
            print(f"Unexpected error: {error} on attempt {attempt + 1}")
            return None, None

    print("Error: Failed to read sensor data after multiple retries.")
    return None, None

# Main program loop
if __name__ == "__main__":
    try:
        while True:
            temperature, humidity = read_dht22_data()

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                print("Temperature: N/A, Humidity: N/A")

            time.sleep(3)  # Wait 3 seconds before the next reading

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")

