"""
Raspberry Pi Python library for Aosong DHT20 Temperature and Humidity Sensor with CRC verification.
https://github.com/cjee21/RPi-DHT20

Robust production-ready version with comprehensive error handling, performance optimizations,
detailed documentation, and adherence to best practices.
"""

import time
import smbus2 as smbus
import logging
from typing import Tuple, Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_BUS = 1
DEFAULT_ADDRESS = 0x76
RETRY_COUNT = 3
MEASUREMENT_ATTEMPTS = 5
MEASUREMENT_INTERVAL = 2  # seconds
MOVING_AVERAGE_WINDOW = 5


class DHT20Error(Exception):
    """Base class for DHT20 exceptions."""
    pass


class SensorCommunicationError(DHT20Error):
    """Raised when I2C communication fails."""
    pass


class CRCError(DHT20Error):
    """Raised when CRC check fails."""
    pass


class DHT20:
    """
    A class to represent the Aosong DHT20 temperature and humidity sensor.
    """

    def __init__(self, bus: int = DEFAULT_BUS, address: int = DEFAULT_ADDRESS) -> None:
        """
        Initializes the DHT20 sensor object.

        Args:
            bus: The I2C bus number.
            address: The I2C address of the DHT20 sensor.
        """
        self.bus_number = bus
        self.address = address
        self.bus = None  # Initialize bus to None
        self._temperature_history = []
        self._humidity_history = []
        self._last_measurement_time = 0

    def begin(self) -> bool:
        """
        Initializes the I2C bus and the DHT20 sensor.

        Returns:
            True if initialization is successful, False otherwise.
        """
        try:
            self.bus = smbus.SMBus(self.bus_number)
            time.sleep(0.5)  # Wait for sensor to stabilize after power-on
            return self._check_sensor_status()
        except Exception as e:
            logger.error(f"Initialization failed: {e}")
            return False

    def _check_sensor_status(self) -> bool:
        """Checks the sensor status after initialization."""
        for _ in range(RETRY_COUNT):
            try:
                data = self._read_register(0x71, 1)
                if (data[0] & 0x18) == 0x18:
                    return True
                else:
                    logger.warning("Sensor status check failed. Retrying...")
                    time.sleep(0.1)
            except SensorCommunicationError as e:
                logger.error(f"I2C communication error during status check: {e}")
                return False
        logger.error("Sensor status check failed after multiple retries.")
        return False


    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        """
        Retrieves the temperature and humidity from the DHT20 sensor with robust error handling.

        Returns:
            A tuple containing temperature (°C), humidity (%), and a boolean indicating CRC error.
            Returns (None, None, True) on error.
        """
        now = time.time()
        if self._last_measurement_time > 0 and now - self._last_measurement_time < MEASUREMENT_INTERVAL:
            # Return the last known values if within the cooldown period
            if self._temperature_history:
                temperature = self._temperature_history[-1]
                humidity = self._humidity_history[-1]
                return temperature, humidity, False
            else:
                return None, None, False

        temperature, humidity, crc_error = None, None, False
        for _ in range(MEASUREMENT_ATTEMPTS):
            try:
                temperature, humidity, crc_error = self._get_sensor_data()
                if crc_error:
                    logger.warning("CRC error detected. Retrying measurement...")
                else:
                    break  # Exit retry loop if successful
            except DHT20Error as e:
                logger.error(f"Error during measurement: {e}")
                time.sleep(0.1)
        else:
            logger.error("Failed to retrieve valid sensor data after multiple attempts.")
            return None, None, True  # Return CRC error status

        # Update moving average filter
        self._temperature_history.append(temperature)
        self._humidity_history.append(humidity)
        if len(self._temperature_history) > MOVING_AVERAGE_WINDOW:
            self._temperature_history.pop(0)
            self._humidity_history.pop(0)

        self._last_measurement_time = now
        return temperature, humidity, crc_error


    def _get_sensor_data(self) -> Tuple[Optional[float], Optional[float], bool]:
        """Retrieves raw sensor data and performs CRC check."""

        self._write_register(0xac, [0x33, 0x00])
        time.sleep(0.08)  # Wait for measurement

        data = self._read_register(0x71, 7)
        if data is None:
            raise SensorCommunicationError("Failed to read sensor data after measurement.")

        temperature_raw = ((data[3] & 0xf) << 16) + (data[4] << 8) + data[5]
        humidity_raw = ((data[3] & 0xf0) >> 4) + (data[1] << 12) + (data[2] << 4)

        temperature = float(temperature_raw) / 5242.88 - 50
        humidity = float(humidity_raw) / 0x100000 * 100

        crc_error = self._calculate_crc(data) != data[6]
        return temperature, humidity, crc_error


    def _calculate_crc(self, data: bytes) -> int:
        """Calculates the CRC-8 checksum."""
        crc = 0xFF
        for i in data[:-1]:
            crc ^= i
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc = crc << 1
        return crc & 0xFF

    def _read_register(self, register: int, length: int) -> Optional[bytes]:
        """Reads data from the specified I2C register with error handling."""
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except OSError as e:
            logger.error(f"I2C read error: {e}")
            return None

    def _write_register(self, register: int, data: list) -> None:
        """Writes data to the specified I2C register with error handling."""
        try:
            self.bus.write_i2c_block_data(self.address, register, data)
        except OSError as e:
            logger.error(f"I2C write error: {e}")

    def close(self) -> None:
        """Closes the I2C bus connection."""
        if self.bus:
            try:
                self.bus.close()
                logger.info("I2C bus closed successfully.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")

    def __enter__(self):
        """Context manager entry point."""
        if not self.begin():
            raise IOError("DHT20 initialization failed")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point."""
        self.close()


if __name__ == "__main__":
    """Demonstration of the DHT20 sensor usage."""

    def main():
        """Main function to demonstrate sensor usage."""
        with DHT20() as sensor:
            try:
                while True:
                    temperature, humidity, crc_error = sensor.get_temperature_and_humidity()
                    if crc_error:
                        logger.warning("CRC error detected.")
                    if temperature is not None and humidity is not None:
                        logger.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    time.sleep(1)
            except KeyboardInterrupt:
                logger.info("Exiting program.")
            except Exception as e:
                logger.exception(f"An unexpected error occurred: {e}")

    if __name__ == "__main__":
        main()

