GPIO.setmode(GPIO.BCM)

def read_dht_data():
    """Reads temperature and humidity from the DHT11 sensor."""
    try:
        humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
        return temperature, humidity
    except Exception as e:
        print(f"Error reading DHT11 sensor: {e}")
        return None, None

def post_data_to_api(temperature, humidity):
    """Posts temperature and humidity data to the local API endpoint."""
    if temperature is not None and humidity is not None:
        payload = {'temperature': temperature, 'humidity': humidity}
        try:
            response = requests.post(API_ENDPOINT, json=payload)
            print(f'API Response: {response.status_code}')
        except requests.exceptions.RequestException as e:
            print(f"Error posting data to API: {e}")

def main():
    """Main function to read sensor data and post it to the API."""
    try:
        while True:
            temperature, humidity = read_dht_data()
            if temperature is not None and humidity is not None:
                print(f'Temperature: {temperature}°C, Humidity: {humidity}%')
                post_data_to_api(temperature, humidity)
            else:
                print("Failed to retrieve data from DHT11 sensor.")
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

