import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0


def read_sensor_data(serial_connection):
    """Reads temperature and humidity data from the serial sensor."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = line.split(',')
            return float(temperature), float(humidity)
        return None, None
    except ValueError as e:
        logging.error(f"Data format error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Error reading data: {e}")
        return None, None


def process_sensor_data(temperature, humidity):
    """Processes sensor data and triggers alerts."""
    if temperature is not None and humidity is not None:
        logging.info(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
        if temperature > TEMPERATURE_THRESHOLD:
            logging.warning(f"High temperature alert: {temperature:.1f}C")
        if humidity > HUMIDITY_THRESHOLD:
            logging.warning(f"High humidity alert: {humidity:.1f}%")


def write_data_to_file(serial_connection, file_path):
    """Writes sensor data to a file."""
    try:
        with open(file_path, 'a') as log_file:
            temperature, humidity = read_sensor_data(serial_connection)
            if temperature is not None and humidity is not None:
                log_file.write(f"{temperature:.1f},{humidity:.1f}\n")
    except Exception as e:
        logging.error(f"Error writing to file: {e}")


def main():
    """Main function to read and process sensor data."""
    serial_connection = None
    try:
        # Initialize serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        logging.info(f"Connected to serial port {SERIAL_PORT}")

        while True:
            temperature, humidity = read_sensor_data(serial_connection)
            if temperature is not None and humidity is not None:
                process_sensor_data(temperature, humidity)
            write_data_to_file(serial_connection, 'temperature_humidity.log')
            time.sleep(1)

    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial port closed.")


if __name__ == "__main__":
    main()

