import time
import signal
import sys
from smbus2 import SMBus
from gpiozero import OutputDevice
from seesaw.seesaw import Seesaw

# Sensor and pump GPIO pins (BCM numbering)
I2C_BUS = 1
I2C_ADDRESS = 0x36
MOISTURE_THRESHOLD = 300
PUMP_PIN = 17

# Global flag for clean exit
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C to stop the pump and exit cleanly."""
    global running
    print("Exiting gracefully...")
    running = False

def read_moisture(seesaw_sensor):
    """Reads moisture level from the sensor."""
    try:
        return seesaw_sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture: {e}")
        return None

def control_pump(pump, moisture_level):
    """Controls the water pump based on moisture level."""
    if moisture_level is not None:
        if moisture_level < MOISTURE_THRESHOLD:
            if not pump.is_active:
                pump.on()
                print("Water pump ON: Soil too dry")
        else:
            if pump.is_active:
                pump.off()
                print("Water pump OFF: Soil moisture sufficient")

def main():
    """Main program loop."""
    global running

    # Initialize the I2C bus
    try:
        bus = SMBus(I2C_BUS)
        seesaw_sensor = Seesaw(bus, addr=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing I2C or seesaw: {e}")
        sys.exit(1)

    # Initialize the water pump
    try:
        water_pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error initializing pump: {e}")
        sys.exit(1)

    # Register the signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)

    print("Soil moisture monitoring started. Press Ctrl+C to exit.")

    try:
        while running:
            moisture = read_moisture(seesaw_sensor)
            if moisture is not None:
                print(f"Moisture level: {moisture}")
                control_pump(water_pump, moisture)
            time.sleep(10)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure pump is off and resources are released
        water_pump.off()
        print("Water pump turned off. Exiting.")

if __name__ == "__main__":
    main()

