def check_power_status():
    """Check power status and trigger alert if needed."""
    if GPIO.input(VOLTAGE_STATUS_PIN) == GPIO.LOW:
        print("Power failure detected!")
        try:
            requests.post(ALERT_ENDPOINT, json={"alert": "Power failure detected"})
        except requests.exceptions.RequestException as e:
            print(f"Alert failed: {e}")
        time.sleep(5)  # Wait to avoid repeated alerts
    else:
        print("Power OK")


def main_loop():
    """Main loop to continuously monitor power status."""
    try:
        while True:
            check_power_status()
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")


if __name__ == "__main__":
    main_loop()

