import RPi.GPIO as GPIO
import time
import signal
import sys
import threading

# Constants for GPIO pin directions
INPUT = GPIO.IN
OUTPUT = GPIO.OUT

# Constants for GPIO pin pull-up/down resistors
PUD_OFF = GPIO.PUD_OFF
PUD_UP = GPIO.PUD_UP

# Define a global lock for thread safety
lock = threading.Lock()

def int_to_gpio(pin_int):
    """Maps an integer pin number to its BCM numbering variant."""
    try:
        return int(pin_int)
    except ValueError:
        raise TypeError("Pin number must be an integer.")

def get_gpio_number(pin_int):
    """Returns the BCM numbering pin number for a given pin."""
    return int_to_gpio(pin_int)

class GPIOError(Exception):
    """Base class for GPIO-related exceptions."""
    pass

class InvalidPinConfiguration(GPIOError):
    """Raised when the pin configuration is invalid."""
    pass

class InvalidPinNumber(GPIOError):
    """Raised when the pin number is invalid."""
    pass

class InvalidPinValue(GPIOError):
    """Raised when the pin value is invalid."""
    pass

class UninitializedPin(GPIOError):
    """Raised when a pin is accessed before initialization."""
    pass

class InputPin:
    """Represents a GPIO pin configured for input."""

    def __init__(self, pin_int, name="", pull_up_down=PUD_OFF):
        """Initializes an InputPin object."""
        self.pin_int = pin_int
        self.pin_num = get_gpio_number(pin_int)
        self.name = str(name)  # Convert to string
        self.pull_up_down = pull_up_down
        self.initialized = False
        self.setup()

    def setup(self):
        """Sets up the GPIO pin for input."""
        with lock:  # Protect GPIO access
            try:
                GPIO.setup(self.pin_num, GPIO.IN, pull_up_down=self.pull_up_down)
                self.initialized = True
            except Exception as e:
                raise InvalidPinConfiguration(f"Error setting up input pin {self.pin_int}: {e}")

    def shutdown(self):
        """Does nothing for input pins."""
        pass

    def get_value(self):
        """Reads the value from the GPIO pin."""
        if not self.initialized:
            raise UninitializedPin(f"Pin {self.pin_int} is not initialized.")
        with lock:
            return GPIO.input(self.pin_num)

    def __repr__(self):
        return f"InputPin(pin={self.pin_int}, name='{self.name}', pull_up_down={self.pull_up_down})"


class OutputPin(InputPin):
    """Represents a GPIO pin configured for output."""

    def __init__(self, pin_int, name="", initial_value=0):
        """Initializes an OutputPin object."""
        super().__init__(pin_int, name)
        if initial_value not in (0, 1):
            raise InvalidPinValue("Initial output value must be 0 or 1.")
        self.initial_value = initial_value
        self.setup()

    def setup(self):
        """Sets up the GPIO pin for output."""
        with lock:
            try:
                GPIO.setup(self.pin_num, GPIO.OUT)
                self.set_value(self.initial_value)  # Initial value
                self.initialized = True
            except Exception as e:
                raise InvalidPinConfiguration(f"Error setting up output pin {self.pin_int}: {e}")

    def set_value(self, value):
        """Writes the value to the GPIO pin."""
        if not self.initialized:
            raise UninitializedPin(f"Pin {self.pin_int} is not initialized.")
        if value not in (0, 1):
            raise InvalidPinValue("Output value must be 0 or 1.")
        with lock:
            GPIO.output(self.pin_num, value)

    def get_value(self):
        """Reads the value from the GPIO pin (for output)."""
        return super().get_value()

    def __repr__(self):
        return f"OutputPin(pin={self.pin_int}, name='{self.name}', initial_value={self.initial_value})"


class TriggerPin(OutputPin):
    """Represents an output pin with a trigger capability."""

    def __init__(self, pin_int, name="", pulse_high=True, pulse_time=None):
        """Initializes a TriggerPin object."""
        super().__init__(pin_int, name, 0)
        self.pulse_high = pulse_high
        self.pulse_time = pulse_time if pulse_time is not None else 100  # Default pulse time in microseconds
        self.state = 0  # Current state of the pin

    def trigger(self):
        """Generates a pulse on the GPIO pin."""
        if not self.initialized:
            raise UninitializedPin(f"Pin {self.pin_int} is not initialized.")

        try:
            with lock:
                if self.pulse_high:
                    self.set_value(1)
                    self.state = 1
                    time.sleep(self.pulse_time / 1000000.0)  # Convert microseconds to seconds
                    self.set_value(0)
                    self.state = 0
                else:
                    self.set_value(0)
                    self.state = 0
                    time.sleep(self.pulse_time / 1000000.0)
                    self.set_value(1)
                    self.state = 1
        except Exception as e:
            raise GPIOError(f"Error triggering pin {self.pin_int}: {e}")

    def get_value(self):
        """Returns the current state of the pin (0 or 1)."""
        return self.state

    def __repr__(self):
        return (f"TriggerPin(pin={self.pin_int}, name='{self.name}', pulse_high={self.pulse_high}, "
                f"pulse_time={self.pulse_time})")


def safe_gpio_cleanup():
    """Safely cleans up the GPIO pins."""
    with lock:
        GPIO.cleanup()


def signal_handler(sig, frame):
    """Handles signals for clean shutdown."""
    print("\nExiting gracefully...")
    safe_gpio_cleanup()
    sys.exit(0)


def main():
    """Main function to demonstrate pin usage."""
    signal.signal(signal.SIGINT, signal_handler)

    try:
        example_trigger = TriggerPin(20, "Example Trigger", pulse_high=True, pulse_time=100)
        example_output = OutputPin(21, "Example Output", initial_value=0)

        print(example_trigger)
        print(example_output)

        example_trigger.trigger()
        time.sleep(0.5)
        example_trigger.trigger()

    except GPIOError as e:
        print(f"GPIO Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        safe_gpio_cleanup()


if __name__ == "__main__":
    main()

