import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Configuration
LED_PIN = 18
TSL2561_ADDR = 0x39
PWM_FREQUENCY = 1000

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_ADDR)
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_gpio():
    """Configure the LED pin as output and start PWM."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT)
    pwm_led = GPIO.PWM(LED_PIN, PWM_FREQUENCY)
    pwm_led.start(0)
    return pwm_led

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def set_led_brightness(pwm_led, lux_value):
    """Set the LED brightness based on the light level."""
    if lux_value is not None:
        brightness = min(100, max(0, lux_value / 10))  # Scale lux to 0-100%
        pwm_led.ChangeDutyCycle(brightness)
    else:
        print("Warning: Could not read light level. Setting LED to 0% brightness.")
        pwm_led.ChangeDutyCycle(0)

