GREEN_PIN = 27
BLUE_PIN = 22

# Define PWM frequency
PWM_FREQUENCY = 200

# Define color sequences
COLOR_SEQUENCES = [
    [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0), (0, 255, 255)],  # Red, Green, Blue, Yellow, Cyan
    [(0, 255, 0), (0, 0, 255), (255, 255, 0), (0, 255, 255), (255, 0, 0)],  # Green, Blue, Yellow, Cyan, Red
    [(0, 0, 255), (255, 255, 0), (0, 255, 255), (255, 0, 0), (0, 255, 0)],  # Blue, Yellow, Cyan, Red, Green
    [(255, 255, 0), (0, 255, 255), (255, 0, 0), (0, 255, 0), (0, 0, 255)],  # Yellow, Cyan, Red, Green, Blue
    [(0, 255, 255), (255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0)]   # Cyan, Red, Green, Blue, Yellow
]


def setup_gpio():
    """Set up GPIO mode and pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RED_PIN, GPIO.OUT)
        GPIO.setup(GREEN_PIN, GPIO.OUT)
        GPIO.setup(BLUE_PIN, GPIO.OUT)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        raise


def create_pwm_channels():
    """Create PWM channels for each color."""
    try:
        red_pwm = GPIO.PWM(RED_PIN, PWM_FREQUENCY)
        green_pwm = GPIO.PWM(GREEN_PIN, PWM_FREQUENCY)
        blue_pwm = GPIO.PWM(BLUE_PIN, PWM_FREQUENCY)
        return red_pwm, green_pwm, blue_pwm
    except Exception as e:
        print(f"Error creating PWM channels: {e}")
        raise


def start_pwm(red_pwm, green_pwm, blue_pwm):
    """Start PWM with initial duty cycles of 0."""
    try:
        red_pwm.start(0)
        green_pwm.start(0)
        blue_pwm.start(0)
    except Exception as e:
        print(f"Error starting PWM: {e}")
        raise


def set_color(red_pwm, green_pwm, blue_pwm, color):
    """Set the RGB LED color using PWM."""
    try:
        red_pwm.ChangeDutyCycle(color[0])
        green_pwm.ChangeDutyCycle(color[1])
        blue_pwm.ChangeDutyCycle(color[2])
    except Exception as e:
        print(f"Error setting color: {e}")
        raise


def display_sequence(red_pwm, green_pwm, blue_pwm, sequence, delay=1):
    """Display a sequence of colors with pauses."""
    try:
        for color in sequence:
            set_color(red_pwm, green_pwm, blue_pwm, color)
            time.sleep(delay)
    except Exception as e:
        print(f"Error displaying sequence: {e}")
        raise


def cleanup_gpio(red_pwm, green_pwm, blue_pwm):
    """Stop PWM and cleanup GPIO."""
    try:
        red_pwm.stop()
        green_pwm.stop()
        blue_pwm.stop()
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during cleanup: {e}")


def main():
    """Main function to control the RGB LED."""
    try:
        setup_gpio()
        red_pwm, green_pwm, blue_pwm = create_pwm_channels()
        start_pwm(red_pwm, green_pwm, blue_pwm)

        for sequence in COLOR_SEQUENCES:
            print(f"Displaying sequence: {sequence}")
            display_sequence(red_pwm, green_pwm, blue_pwm, sequence)

    except KeyboardInterrupt:
        print("Exiting program due to keyboard interrupt.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Cleaning up GPIO...")
        if 'red_pwm' in locals() and 'green_pwm' in locals() and 'blue_pwm' in locals():
            cleanup_gpio(red_pwm, green_pwm, blue_pwm)
        else:
            print("PWM objects not initialized, skipping cleanup.")


if __name__ == "__main__":
    main()

