import RPi.GPIO as GPIO
import time
import datetime

# Define the GPIO pin connected to the relay
RELAY_PIN = 17

# Define the sunrise and sunset times (24-hour format)
SUNRISE_TIME = datetime.time(7, 0, 0)
SUNSET_TIME = datetime.time(19, 0, 0)

def setup_gpio():
    """Sets up the GPIO pin for the relay."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
        GPIO.output(RELAY_PIN, GPIO.HIGH)  # Initialize to closed state
        print("GPIO setup complete.")
    except RuntimeError as e:
        print(f"Error setting up GPIO: {e}")
        exit()

def is_time_between(start_time, end_time):
    """Checks if the current time is between the start and end times."""
    now = datetime.datetime.now().time()
    if start_time <= end_time:
        return start_time <= now <= end_time
    else:  # Handle the case where the sunset is on the next day
        return now >= start_time or now <= end_time

def control_door(open_door):
    """Controls the chicken coop door (open or close)."""
    try:
        if open_door:
            GPIO.output(RELAY_PIN, GPIO.LOW)  # Open the door (activate relay)
            print("Chicken coop door opened.")
        else:
            GPIO.output(RELAY_PIN, GPIO.HIGH) # Close the door (deactivate relay)
            print("Chicken coop door closed.")
    except Exception as e:
        print(f"Error controlling door: {e}")

def main():
    """Main function to control the chicken coop door."""
    setup_gpio()

    try:
        while True:
            # Check if it's daytime (sunrise to sunset)
            if is_time_between(SUNRISE_TIME, SUNSET_TIME):
                control_door(True)  # Open the door
            else:
                control_door(False) # Close the door

            time.sleep(60)  # Check every minute

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

