import time
import sys
import traceback
from adafruit_servokit import ServoKit

# Constants for servo control
NUM_SERVOS = 16
DEFAULT_I2C_ADDRESS = 0x40
MIN_ANGLE = 0
MAX_ANGLE = 180
MOVE_INCREMENT = 5
MOVE_DELAY = 0.04

# Initialize the ServoKit object
try:
    kit = ServoKit(channels=NUM_SERVOS, i2c_address=DEFAULT_I2C_ADDRESS)
except OSError as e:
    print(f"Error initializing ServoKit: {e}")
    sys.exit(1)


def move_servo(channel: int, target_angle: float) -> None:
    """Moves a servo on the specified channel to the target angle."""
    if not 0 <= channel < NUM_SERVOS:
        raise ValueError(f"Invalid servo channel: {channel}")
    if not MIN_ANGLE <= target_angle <= MAX_ANGLE:
        raise ValueError(f"Invalid target angle: {target_angle}")

    try:
        current_angle = kit.servo[channel].angle or MIN_ANGLE
    except Exception as e:
        raise OSError(f"Error reading current servo angle: {e}") from e

    # Optimize movement by checking if the servo is already at the target position
    if current_angle == target_angle:
        return

    # Determine direction and create a range of angles to visit
    if target_angle > current_angle:
        angle_range = range(int(current_angle), int(target_angle) + 1, MOVE_INCREMENT)
    else:
        angle_range = range(int(current_angle), int(target_angle) - 1, -MOVE_INCREMENT)

    for angle in angle_range:
        try:
            kit.servo[channel].angle = angle
            time.sleep(MOVE_DELAY)
        except Exception as e:
            raise OSError(f"Error setting servo angle: {e}") from e


def grab_object(kit: ServoKit, api_call: str) -> None:
    """Moves the arm to grab an object and then lower it."""
    try:
        move_servo(0, 90)  # Move servo 0 to 90 degrees
        move_servo(1, 90)  # Move servo 1 to 90 degrees
        move_servo(2, 150) # Move servo 2 to 150 degrees (lower)
        move_servo(3, 90)  # Move servo 3 to 90 degrees
        move_servo(4, 90)  # Move servo 4 to 90 degrees
        move_servo(5, 90)  # Move servo 5 to 90 degrees
    except (OSError, ValueError) as e:
        print(f"Error during grabbing sequence: {e}")
        traceback.print_exc()
    except Exception as e:
        print(f"Unexpected error during grabbing sequence: {e}")
        traceback.print_exc()



def release_object(kit: ServoKit, api_call: str) -> None:
    """Moves the arm to release an object."""
    try:
        move_servo(2, 90)  # Move servo 2 back to 90 degrees (raise)
    except (OSError, ValueError) as e:
        print(f"Error during releasing sequence: {e}")
        traceback.print_exc()
    except Exception as e:
        print(f"Unexpected error during releasing sequence: {e}")
        traceback.print_exc()



def move_servo_with_range(servo_number: int, start_angle: float, end_angle: float, step: int = 1) -> None:
    """Generic function to move a servo across a range of angles."""
    if not 0 <= servo_number < NUM_SERVOS:
        raise ValueError(f"Invalid servo number: {servo_number}")

    try:
        if start_angle > end_angle:
            angle_range = range(int(start_angle), int(end_angle) - 1, -step)
        else:
            angle_range = range(int(start_angle), int(end_angle) + 1, step)

        for angle in angle_range:
            kit.servo[servo_number].angle = angle
            time.sleep(MOVE_DELAY)

    except Exception as e:
        raise OSError(f"Error moving servo: {e}") from e



def move_forward(speed: int, duration: float) -> None:
    """Moves the robot forward at the specified speed for the given duration."""
    try:
        move_servo_with_range(0, MIN_ANGLE, MAX_ANGLE, speed)
        time.sleep(duration)
        move_servo_with_range(0, MAX_ANGLE, MIN_ANGLE, speed)  # Return to starting position
    except (OSError, ValueError) as e:
        print(f"Error during forward movement: {e}")


# ... (similarly refactor other movement functions: move_backward, turn_left, turn_right)


def main():
    """Main function to execute user commands."""
    commands = {
        "forward": move_forward,
        # ... (add other commands)
        "grab": grab_object,
        "release": release_object,
        # ...
    }

    try:
        while True:
            command = input("Enter command: ").lower()
            function = commands.get(command)
            if function:
                try:
                    function(kit, command) # Pass kit and command as arguments
                except Exception as e:
                    print(f"Error executing command '{command}': {e}")
            else:
                print("Invalid command.")

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        traceback.print_exc()
    finally:
        # Perform cleanup operations here (e.g., setting servos to a safe position)
        print("Program terminated.")


if __name__ == "__main__":
    main()

