#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Driver for the Maxim DS1338 Real-Time Clock (RTC) using I2C.

This module provides a class for interacting with the DS1338 RTC on a Raspberry Pi.
It allows reading and writing date and time information to the RTC.
"""

import smbus2
import time
import logging
from datetime import datetime, timedelta, tzinfo

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DS1338:
    """Driver class for the Maxim DS1338 RTC."""

    # Register addresses for the DS1338
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07
    REG_STATUS = 0x0F  # Added Status Register address

    def __init__(self, i2c_bus_number=1, device_address=0x68, use_virtual_bus=False):
        """
        Initializes the DS1338 RTC driver.

        Args:
            i2c_bus_number (int): The I2C bus number (default: 1).
            device_address (int): The I2C address of the DS1338 (default: 0x68).
            use_virtual_bus (bool): Use the virtual I2C bus for testing (default: False).
        """
        try:
            if use_virtual_bus:
                self.bus = smbus2.SMBus(i2c_bus_number)
            else:
                self.bus = smbus2.SMBus(i2c_bus_number)
            self.device_address = device_address
            logging.info("DS1338 initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize DS1338: {e}")
            raise

    def __enter__(self):
        """Context manager entry point."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closing the bus."""
        try:
            self.bus.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
            return True  # Suppress exception

    def _write_register(self, register, data):
        """Writes a byte of data to a specific register."""
        try:
            self.bus.write_byte_data(self.device_address, register, data)
            logging.debug(f"Wrote 0x{data:02X} to register 0x{register:02X}")
        except OSError as e:
            logging.error(f"I2C write error: {e}")
            raise IOError(f"I2C write error to address 0x{self.device_address:02X}, register 0x{register:02X}") from e

    def _read_register(self, register):
        """Reads a byte of data from a specific register."""
        try:
            data = self.bus.read_byte_data(self.device_address, register)
            logging.debug(f"Read 0x{data:02X} from register 0x{register:02X}")
            return data
        except OSError as e:
            logging.error(f"I2C read error: {e}")
            raise IOError(f"I2C read error from address 0x{self.device_address:02X}, register 0x{register:02X}") from e

    def _bcd_to_int(self, bcd):
        """Converts a BCD value to an integer."""
        try:
            return (bcd >> 4) * 10 + (bcd & 0x0F)
        except TypeError as e:
            logging.error(f"Invalid BCD value: {bcd}")
            raise ValueError(f"Invalid BCD value: {bcd}") from e

    def _int_to_bcd(self, integer):
        """Converts an integer to BCD format."""
        if not 0 <= integer <= 99:
            raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
        return (integer // 10 << 4) | (integer % 10)

    def read_all(self):
        """Reads all time registers and returns a tuple of values."""
        try:
            data = self.bus.read_i2c_block_data(self.device_address, self.REG_SECONDS, 7)
            logging.debug(f"Read 7 bytes: {data}")

            seconds = self._bcd_to_int(data[0] & 0x7F)
            minutes = self._bcd_to_int(data[1])
            hours = self._bcd_to_int(data[2] & 0x3F)
            day = self._bcd_to_int(data[3])
            date = self._bcd_to_int(data[4])
            month = self._bcd_to_int(data[5])
            year = self._bcd_to_int(data[6])
            return year, month, date, day, hours, minutes, seconds
        except OSError as e:
            logging.error(f"I2C read error: {e}")
            raise IOError(f"I2C read error from address 0x{self.device_address:02X}") from e


    def read_datetime(self, century=21):
        """Reads the time and returns a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()

            # DS1338 returns 21-century years starting from the register value,
            # but we store dates as years relative to 2000.  Adjust for this.
            rtc_year = (century - 1) * 100 + year
            current_year = datetime.now().year
            rtc_year -= (1900, 2000)[2000 <= current_year < 2100]  # Adjust for common years

            dt = datetime(rtc_year, month, date, hours, minutes, seconds)
            logging.info(f"RTC time: {dt}")
            return dt.replace(tzinfo=tzinfo())  # Add default timezone info
        except Exception as e:
            logging.error(f"Error reading datetime: {e}")
            raise

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Writes all time registers."""
        try:
            data = [
                self._int_to_bcd(seconds & 0x7F),
                self._int_to_bcd(minutes),
                self._int_to_bcd(hours),
                self._int_to_bcd(day),
                self._int_to_bcd(date),
                self._int_to_bcd(month),
                self._int_to_bcd(year % 100),  # Store year as last two digits
            ]
            self.bus.write_i2c_block_data(self.device_address, self.REG_SECONDS, data)
            logging.info(f"Time written to RTC: {year}-{month}-{date} {hours}:{minutes}:{seconds}")
        except OSError as e:
            logging.error(f"I2C write error: {e}")
            raise IOError(f"I2C write error to address 0x{self.device_address:02X}") from e

    def write_datetime(self, dt, validate_values=True):
        """Writes the datetime object to the RTC."""
        try:
            if validate_values:
                if not 1900 <= dt.year <= 2100:
                    raise ValueError("Year must be between 1900 and 2100")
                if not 1 <= dt.month <= 12:
                    raise ValueError("Month must be between 1 and 12")
                if not 1 <= dt.day <= 31:
                    raise ValueError("Day must be between 1 and 31")
                if not 0 <= dt.hour <= 23:
                    raise ValueError("Hour must be between 0 and 23")
                if not 0 <= dt.minute <= 59:
                    raise ValueError("Minute must be between 0 and 59")
                if not 0 <= dt.second <= 59:
                    raise ValueError("Second must be between 0 and 59")

            self.write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(),
                           dt.hour, dt.minute, dt.second)
        except Exception as e:
            logging.error(f"Error writing datetime: {e}")
            raise

    def write_now(self):
        """Writes the current time to the RTC."""
        try:
            now = datetime.now()
            self.write_datetime(now)
        except Exception as e:
            logging.error(f"Error writing current time: {e}")
            raise


class tzinfo(tzinfo):
    """Minimal tzinfo implementation."""

    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)


if __name__ == '__main__':
    try:
        with DS1338(device_address=0x68) as rtc:
            rtc.write_now()
            current_time = rtc.read_datetime()
            logging.info(f"Current time: {current_time}")
    except IOError as e:
        logging.error(f"DS1338 I2C error: {e}")
        exit(0)
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
        exit(1)

