import serial
import time
import RPi.GPIO as GPIO
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1

def initialize_serial(port, baudrate, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Initialize to LOW

def read_radiation_level(serial_port):
    """Reads a line from the serial port and returns the radiation level as a float."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        logging.warning("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        logging.error(f"Serial read error: {e}")
        return None

def control_alarm(pin, level, threshold):
    """Controls the alarm based on the radiation level and threshold."""
    if level is not None:
        alarm_active = level > threshold
        GPIO.output(pin, GPIO.HIGH if alarm_active else GPIO.LOW)
        return alarm_active
    return GPIO.input(pin)  # Return current alarm state

def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return  # Exit if serial port initialization fails

    initialize_gpio(ALARM_GPIO_PIN)
    alarm_state = False

    try:
        while True:
            radiation_level = read_radiation_level(serial_connection)

            if radiation_level is not None:
                logging.info(f"Radiation Level: {radiation_level:.2f} µSv/h")

                new_alarm_state = control_alarm(ALARM_GPIO_PIN, radiation_level, RADIATION_THRESHOLD)

                if new_alarm_state != alarm_state:
                    alarm_state = new_alarm_state
                    logging.info(f"Alarm {'ACTIVE' if alarm_state else 'INACTIVE'}")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        logging.info("Serial port closed and GPIO cleaned up.")

if __name__ == "__main__":
    main()

