import serial
import time
import logging

# Configure logging
logging.basicConfig(filename='gps_coordinates_log.txt', level=logging.INFO, 
                    format='%(asctime)s - %(message)s')

def parse_gga_data(data):
    """Parses GPGGA NMEA sentence to extract latitude, longitude, and altitude."""
    try:
        if data.startswith('$GPGGA'):
            parts = data.split(',')
            if parts[6] == '1':  # Check for valid fix
                latitude = parts[2]
                longitude = parts[4]
                altitude = parts[9]
                return latitude, longitude, altitude
        return None, None, None
    except Exception as e:
        print(f"Error parsing GPGGA data: {e}")
        return None, None, None

def log_coordinates(latitude, longitude, altitude):
    """Logs the coordinates to a file with a timestamp."""
    try:
        with open('gps_coordinates_log.txt', 'a') as log_file:
            log_file.write(f'{time.strftime("%Y-%m-%dT%H:%M:%S")} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n')
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read GPS data and log coordinates."""
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        print("GPS data logging started. Press Ctrl+C to stop.")
        while True:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                latitude, longitude, altitude = parse_gga_data(line)
                if latitude and longitude and altitude:
                    print(f'Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m')
                    log_coordinates(latitude, longitude, altitude)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
            time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to initialize serial port: {e}")
    except KeyboardInterrupt:
        print("Logging stopped by user.")
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

