import json
import time
import threading
from threading import Lock
import logging
from flask import Flask, Response, request, abort, jsonify
import serial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
SERIAL_TIMEOUT = 1  # seconds
APP = Flask(__name__)
DATA_LOCK = Lock()
DATA_STORE = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": True}]
NEXT_ID = len(DATA_STORE) + 1


class SerialConnection:
    """Manages the serial connection and communication with the instrument."""

    def __init__(self, port=DEFAULT_SERIAL_PORT, baudrate=DEFAULT_BAUDRATE, timeout=SERIAL_TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self.lock = Lock()  # Lock for serial operations

    def open(self):
        """Opens the serial port."""
        with self.lock:
            try:
                self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
                logging.info(f"Serial port {self.port} opened successfully.")
                return True
            except serial.SerialException as e:
                logging.error(f"Error opening serial port {self.port}: {e}")
                return False

    def close(self):
        """Closes the serial port."""
        with self.lock:
            if self.ser and self.ser.is_open:
                self.ser.close()
                logging.info(f"Serial port {self.port} closed.")

    def send_command(self, command):
        """Sends a command to the instrument and reads the response."""
        with self.lock:
            if not self.ser or not self.ser.is_open:
                logging.error("Serial port is not open.")
                return None

            try:
                self.ser.write(command.encode('ascii'))
                response = self.ser.readline().decode('ascii', errors='replace').strip()
                return response
            except serial.SerialException as e:
                logging.error(f"Serial communication error: {e}")
                return None


def get_instrument_version(serial_connection):
    """Queries the instrument for its version information."""
    if not serial_connection.open():
        logging.error("Failed to open serial connection.")
        return "Error: Could not open serial connection."

    response = serial_connection.send_command("*IDN?\n")
    if response:
        logging.info(f"Instrument response: {response}")
    else:
        logging.error("No response received from the instrument.")
        return "Error: No response received."

    serial_connection.close()
    return response


@APP.route('/version', methods=['GET'])
def version_endpoint():
    """Endpoint to retrieve the instrument's version information."""
    serial_connection = SerialConnection()
    version_info = get_instrument_version(serial_connection)
    return Response(version_info + '\n', mimetype='text/plain')


@APP.route('/data', methods=['GET'])
def get_all_data():
    """Endpoint to retrieve all data items."""
    with DATA_LOCK:
        return jsonify(DATA_STORE)


@APP.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    """Endpoint to retrieve a specific data item by ID."""
    with DATA_LOCK:
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            return jsonify(item)
        else:
            abort(404)


@APP.route('/data', methods=['POST'])
def create_data_item():
    """Endpoint to create a new data item."""
    if not request.json or 'name' not in request.json:
        abort(400, description="Request body must contain 'name'")

    with DATA_LOCK:
        global NEXT_ID
        new_item = {
            "id": NEXT_ID,
            "name": request.json['name'],
            "done": request.json.get('done', False)  # Default to False if 'done' is not provided
        }
        DATA_STORE.append(new_item)
        NEXT_ID += 1
        return jsonify(new_item), 201


if __name__ == '__main__':
    try:
        APP.run(debug=False, host='0.0.0.0', port=5000)
    except KeyboardInterrupt:
        logging.info("Shutting down server...")
    finally:
        serial_connection = SerialConnection()
        serial_connection.close()
        logging.info("Server stopped.")

