from flask import Flask, Response, request, jsonify, abort

app = Flask(__name__)

# In-memory data store (could be replaced with a database later)
DATA = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "gizmos", "done": False}]

# Serial port configuration (adjust as needed)
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUD = 9600
SERIAL_TIMEOUT = 1  # seconds


def get_serial_connection():
    """Establishes a serial connection."""
    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUD, timeout=SERIAL_TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def close_serial_connection(ser):
    """Closes a serial connection."""
    if ser and ser.is_open:
        try:
            ser.close()
            print("Serial port closed.")
        except serial.SerialException as e:
            print(f"Error closing serial port: {e}")


@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Queries the instrument for its version information."""
    ser = get_serial_connection()
    if not ser:
        return Response("Serial port unavailable", status=503, mimetype='text/plain')

    try:
        ser.write(b"*IDN?\n")  # Send the query command
        time.sleep(0.1)  # Give the instrument some time to respond
        response = ser.read(1000).decode('utf-8', errors='ignore')  # Read up to 1000 bytes
