import serial
import time

# Define the Bluetooth device and settings
bluetooth_device = "/dev/rfcomm4"
bluetooth_baudrate = 38400
bluetooth_port = None

def initialize_bluetooth():
    """Initializes the Bluetooth serial connection."""
    global bluetooth_port
    try:
        bluetooth_port = serial.Serial(bluetooth_device, bluetooth_baudrate)
        print(f"Connected to Bluetooth on {bluetooth_device}")
    except serial.SerialException as e:
        raise RuntimeError(f"Error connecting to Bluetooth: {e}")

def send_command(command_string):
    """Sends a command to the Bluetooth device."""
    global bluetooth_port
    if bluetooth_port is None:
        raise RuntimeError("Bluetooth connection not initialized.")

    try:
        full_command = f"X{command_string}\n"  # Add newline for clear message boundaries
        bluetooth_port.write(full_command.encode())
        print(f"Sent command: {command_string}")
        time.sleep(0.1)  # Add a small delay to prevent overwhelming the device
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")

def main():
    """Main function to handle user input and send commands."""
    try:
        initialize_bluetooth()
        while True:
            try:
                user_input = input("Enter command (or 'exit'): ")
                if user_input.lower() == "exit":
                    break
                send_command(user_input)
            except RuntimeError as e:
                print(f"Error: {e}")
                break  # Exit on critical errors
            except KeyboardInterrupt:
                print("\nExiting...")
                break
    finally:
        if bluetooth_port:
            bluetooth_port.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

